ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "ici_name", "trial_phase", "cancer_type", "trial_name", "treatment_regimen"
FROM public."clinical_trials"
WHERE "ici_name" = 'Pembrolizumab' AND "cancer_type" = 'Esophageal/GEJ' AND "trial_phase" = 'Phase 3';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "name_of_ici", "trial_phase", "cancer_type", "trial_name", "treatment_regimen"
FROM public."clinical_trials"
WHERE "name_of_ici" = 'Pembrolizumab' AND "cancer_type" = 'Esophageal/GEJ' AND "trial_phase" = 'Phase 3';
